"""Structured event logger for synaptory.

Writes JSONL to .synaptory/.orchestrator/events.jsonl with a stable
correlation ID (SYNAPTORY_CHAIN_ID) and agent depth (SYNAPTORY_AGENT_DEPTH) on every
line. Addresses audit findings H9-F1 (observability) and BEA4-F1/H7-F1
(recursive-fork guard via depth tracking).

Usage:
    from synaptory_logger import emit, chain_id, agent_depth

    emit("transition", story_id="US-042", from_state="testing", to="reviewing")

CLI:
    # Emit an event from shell hooks:
    python3 synaptory_logger.py <project_dir> <event_type> [key=value ...]

Design:
- Chain ID is minted on first touch and persisted to
  .synaptory/.orchestrator/chain-id so every process in the project shares
  the same ID until it is rotated manually. Environment variable
  SYNAPTORY_CHAIN_ID overrides the file (for subagent propagation).
- Depth is read from SYNAPTORY_AGENT_DEPTH env var only. The orchestrator sets
  it to 1 on the first Task() dispatch; subagents must increment it
  before dispatching further.
- Sink is append-only JSONL. Rotated at 10 MiB to .jsonl.1 (keep one).
"""
from __future__ import annotations

import json
import os
import sys
import time
import uuid
from pathlib import Path
from typing import Any

CHAIN_ID_ENV = "SYNAPTORY_CHAIN_ID"
AGENT_DEPTH_ENV = "SYNAPTORY_AGENT_DEPTH"
MAX_AGENT_DEPTH = 3  # Hard cap enforced by SubagentStart hook (BEA4-F1 / H7-F1)
_ROTATE_BYTES = 10 * 1024 * 1024


def _orchestrator_dir(project_dir: str | os.PathLike[str]) -> Path:
    return Path(project_dir) / ".synaptory" / ".orchestrator"


def _chain_id_file(project_dir: str | os.PathLike[str]) -> Path:
    return _orchestrator_dir(project_dir) / "chain-id"


def chain_id(project_dir: str | os.PathLike[str] | None = None) -> str:
    """Return the current chain ID, minting one if needed.

    Precedence: SYNAPTORY_CHAIN_ID env var > persisted file > freshly minted UUID.
    """
    env = os.environ.get(CHAIN_ID_ENV)
    if env:
        return env
    if project_dir is None:
        project_dir = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    path = _chain_id_file(project_dir)
    try:
        if path.exists():
            existing = path.read_text().strip()
            if existing:
                return existing
    except OSError:
        pass
    new_id = uuid.uuid4().hex
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(new_id + "\n")
    except OSError:
        # Directory not writable (e.g. plugin dry-run); fall back to env-only.
        pass
    return new_id


def agent_depth() -> int:
    """Return the current agent depth. Root/orchestrator is 0.

    Reads SYNAPTORY_AGENT_DEPTH env var if set (fast path for in-process callers).
    Falls back to the active-depth counter file maintained by the
    SubagentStart/SubagentStop hooks so that shell hooks can read a live value
    without requiring the orchestrator to thread env vars through Task() calls.
    """
    raw = os.environ.get(AGENT_DEPTH_ENV)
    if raw is not None:
        try:
            return max(0, int(raw))
        except ValueError:
            pass
    # File-based fallback: read the live counter.
    project_dir = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    counter = _active_depth_file(project_dir)
    try:
        if counter.exists():
            return max(0, int(counter.read_text().strip() or "0"))
    except (OSError, ValueError):
        pass
    return 0


def _active_depth_file(project_dir: str | os.PathLike[str]) -> Path:
    return _orchestrator_dir(project_dir) / "active-depth"


def increment_depth(project_dir: str | os.PathLike[str] | None = None) -> int:
    """Atomically increment the active-depth counter. Returns the new depth.

    Best-effort: on filesystem errors returns a computed fallback. Not safe
    under heavy concurrent subagent spawning, but subagent lifecycle in
    Claude Code is serial enough that a simple read-modify-write is fine.
    """
    if project_dir is None:
        project_dir = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    counter = _active_depth_file(project_dir)
    try:
        counter.parent.mkdir(parents=True, exist_ok=True)
        current = 0
        if counter.exists():
            try:
                current = max(0, int(counter.read_text().strip() or "0"))
            except ValueError:
                current = 0
        new_depth = current + 1
        counter.write_text(str(new_depth))
        return new_depth
    except OSError:
        return agent_depth() + 1


def decrement_depth(project_dir: str | os.PathLike[str] | None = None) -> int:
    """Atomically decrement the active-depth counter, clamped at 0."""
    if project_dir is None:
        project_dir = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    counter = _active_depth_file(project_dir)
    try:
        if not counter.exists():
            return 0
        current = max(0, int(counter.read_text().strip() or "0"))
        new_depth = max(0, current - 1)
        counter.write_text(str(new_depth))
        return new_depth
    except (OSError, ValueError):
        return 0


def _rotate_if_needed(path: Path) -> None:
    try:
        if path.exists() and path.stat().st_size >= _ROTATE_BYTES:
            backup = path.with_suffix(path.suffix + ".1")
            if backup.exists():
                backup.unlink()
            path.rename(backup)
    except OSError:
        # Best-effort rotation — never block emission on rotation errors.
        pass


def emit(
    event: str,
    project_dir: str | os.PathLike[str] | None = None,
    **payload: Any,
) -> None:
    """Append a JSON event to .synaptory/.orchestrator/events.jsonl.

    Never raises — logging must not break pipeline execution. Events that
    cannot be written (missing workspace, permission denied) are silently
    dropped so hooks remain non-blocking.
    """
    if project_dir is None:
        project_dir = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    sink_dir = _orchestrator_dir(project_dir)
    sink = sink_dir / "events.jsonl"
    try:
        sink_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        return

    record = {
        "ts": time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime()) + "Z",
        "chain_id": chain_id(project_dir),
        "depth": agent_depth(),
        "event": event,
    }
    # Keep payload keys out of the reserved set; callers that collide get ignored.
    for k, v in payload.items():
        if k in record:
            continue
        record[k] = v

    try:
        _rotate_if_needed(sink)
        line = json.dumps(record, default=str, ensure_ascii=False)
        with sink.open("a", encoding="utf-8") as f:
            f.write(line + "\n")
    except (OSError, TypeError, ValueError):
        return


def _parse_kv(args: list[str]) -> dict[str, Any]:
    """Parse key=value pairs from CLI args. Values are kept as strings."""
    out: dict[str, Any] = {}
    for a in args:
        if "=" in a:
            k, v = a.split("=", 1)
            out[k] = v
    return out


def main(argv: list[str] | None = None) -> int:
    argv = argv if argv is not None else sys.argv[1:]
    if len(argv) < 2:
        print(
            "Usage:\n"
            "  synaptory_logger.py <project_dir> <event_type> [key=value ...]\n"
            "  synaptory_logger.py <project_dir> --depth-inc   (prints new depth, 0 on error)\n"
            "  synaptory_logger.py <project_dir> --depth-dec\n"
            "  synaptory_logger.py <project_dir> --depth-get\n",
            file=sys.stderr,
        )
        return 1
    project_dir = argv[0]
    action = argv[1]
    if action == "--depth-inc":
        print(increment_depth(project_dir))
        return 0
    if action == "--depth-dec":
        print(decrement_depth(project_dir))
        return 0
    if action == "--depth-get":
        os.environ.setdefault("CLAUDE_PROJECT_DIR", str(project_dir))
        print(agent_depth())
        return 0
    emit(action, project_dir=project_dir, **_parse_kv(argv[2:]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
